() => {
  const bodyText = document.body.innerText;
  // Look for assessment-related info
  const quizMatches = bodyText.match(/(\d+)\s*(quiz|测验)/gi);
  const assignmentMatches = bodyText.match(/(\d+)\s*(assignment|作业|task|任务)/gi);
  return {
    bodyTextSnippet: bodyText.substring(0, 5000),
    quizMatches: quizMatches || [],
    assignmentMatches: assignmentMatches || []
  };
}

() => {
  const bodyText = document.body.innerText;
  const quizMatches = bodyText.match(/(\d+)\s*(quiz|测验)/gi);
  const assignmentMatches = bodyText.match(/(\d+)\s*(assignment|作业|task|任务)/gi);
  return JSON.stringify({
    bodyTextSnippet: bodyText.substring(0, 3000),
    quizMatches: quizMatches || [],
    assignmentMatches: assignmentMatches || []
  });
}

() => {
  const data = __data();
  const courses = data.filter(d => d.course);
  return courses;
}
